internal MainWindow(PenSettingsStore store, string penId, string? desktopDirectory = null)
    {
        this.store = store;
        this.penId = penId;
        itemDesktopDirectory = desktopDirectory ?? Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
        InitializeComponent();
        Icon = AppInfo.CreateWindowIcon();
        settings = store.Load();
        ApplySettings();
        ItemsReady = InitializeItemsAsync();
        saveTimer.Tick += (_, _) => { saveTimer.Stop(); SaveSettings(); };
        LocationChanged += (_, _) => ScheduleSave();
        SizeChanged += (_, _) => ScheduleSave();
        SourceInitialized += (_, _) =>
        {
            surface = new DesktopSurface(new WindowInteropHelper(this).Handle);
            shellTimer.Tick += (_, _) => RefreshSurface();
            shellTimer.Start();
            RefreshSurface();
        };
        Loaded += (_, _) =>
        {
            // StartupUri can show a window after SourceInitialized. Reapply persisted intent.
            if (!settings.IsVisible) Hide();
            RefreshSurface();
        };
        Closing += OnClosing;
        Closed += (_, _) =>
        {
            DisposeItems();
            shellTimer.Stop();
            geometryKeyTimer.Stop();
            saveTimer.Stop();
            if (!deleted) SaveSettings();
            surface?.Dispose();
        };
    }

